/**
 * Where binary PDFs live. Keys are generated by the backend, never by users or AI.
 * Artifacts are immutable: put() must fail if the key already exists.
 * An S3-compatible implementation can replace LocalFileStorage later.
 */
export interface FileStorage {
  put(key: string, data: Buffer): Promise<void>;
  get(key: string): Promise<Buffer>;
  exists(key: string): Promise<boolean>;
}